import { createHash, randomBytes } from 'crypto'
import { type NextRequest } from 'next/server'
import { z } from 'zod'
import { createSupabaseClientForApiRoute } from '@/lib/supabase/api-route-client'
import { createServiceRoleClient } from '@/lib/supabase/service-role'
import { success, error, errorFlatMessage } from '@/lib/api/response'
import { ErrorCodes } from '@/lib/api/errors'
import {
  StaffManagementQueries,
  type UiRole,
} from '@/lib/dashboard/staff-management-queries'
import { resolveDashboardAccess, canManageStaffRoster } from '@/lib/rbac/dashboard-guards'
import { sendEmail } from '@/lib/email/emailit'
import { buildStaffInviteLinkEmailHtml } from '@/lib/email/templates/staff-invite-link'
import { recordActivityLog } from '@/shared/activity-log/record-activity-log'

const STAFF_INVITE_TOKEN_EXPIRY_DAYS = 7

function hashStaffInviteToken(token: string): string {
  return createHash('sha256').update(token).digest('hex')
}

function getInviteBaseUrl(): string {
  return (
    process.env.NEXT_PUBLIC_APP_URL ||
    process.env.NEXT_PUBLIC_BASE_URL ||
    'http://localhost:3000'
  ).replace(/\/$/, '')
}

const BodySchema = z
  .object({
    email: z.string().trim().email(),
    roleCategoryId: z.string().uuid().optional(),
    roleCategoryIds: z.array(z.string().uuid()).optional(),
    status: z.enum(['pending', 'active', 'inactive']).optional(),
    categories: z.array(z.string()).optional(),
  })
  .transform((data) => {
    const roleCategoryIds =
      data.roleCategoryIds && data.roleCategoryIds.length > 0
        ? [...new Set(data.roleCategoryIds)]
        : data.roleCategoryId
          ? [data.roleCategoryId]
          : []
    return {
      email: data.email,
      status: data.status,
      categories: data.categories,
      roleCategoryIds,
    }
  })
  .refine((data) => data.roleCategoryIds.length > 0, {
    message: 'At least one role category id is required',
    path: ['roleCategoryIds'],
  })

function isUiRole(value: string): value is UiRole {
  return value === 'owner' || value === 'admin' || value === 'manager' || value === 'staff'
}

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ propertyId: string }> }
) {
  try {
    const { propertyId } = await params
    const { supabase, user, error: authError } = await createSupabaseClientForApiRoute(request)

    if (authError || !user) {
      console.error('[StaffManagementInviteStaff] Unauthorized', {
        propertyId,
        authError: authError?.message ?? null,
      })
      return errorFlatMessage(
        authError?.message ?? ErrorCodes.AUTH_001.message,
        ErrorCodes.AUTH_001.status,
        request,
      )
    }

    const parsed = BodySchema.safeParse(await request.json())
    if (!parsed.success) {
      return error(ErrorCodes.VALIDATION_ERROR, request, {
        errors: parsed.error.errors,
      })
    }

    const q = new StaffManagementQueries(supabase as any)
    const access = await resolveDashboardAccess(supabase as never, propertyId, user.id)
    if (!access) {
      return errorFlatMessage(
        'No access to this property. Confirm the property ID, and that your user is the company owner or has a property_staff row for this property.',
        ErrorCodes.AUTH_002.status,
        request,
      )
    }

    if (!canManageStaffRoster(access)) {
      return errorFlatMessage(
        'Inviting staff requires an admin-level property role (owner, admin, or property_admin).',
        ErrorCodes.AUTH_002.status,
        request,
      )
    }

    const roleCategoryIds = parsed.data.roleCategoryIds

    const { data: roleCategoryRows, error: roleCategoriesError } = await supabase
      .from('property_role_categories')
      .select('id, role')
      .eq('property_id', propertyId)
      .in('id', roleCategoryIds)

    if (
      roleCategoriesError ||
      !roleCategoryRows ||
      roleCategoryRows.length !== roleCategoryIds.length
    ) {
      return error(ErrorCodes.VALIDATION_ERROR, request, {
        message: 'One or more roleCategoryIds are invalid for this property',
      })
    }

    const firstRole = roleCategoryRows[0]!.role
    if (!roleCategoryRows.every((r) => r.role === firstRole)) {
      return error(ErrorCodes.VALIDATION_ERROR, request, {
        message: 'All role categories must share the same role',
      })
    }

    if (!isUiRole(firstRole)) {
      return error(ErrorCodes.VALIDATION_ERROR, request, {
        message: 'Invalid role on category records',
      })
    }

    const service = createServiceRoleClient()

    let newUserId: string
    try {
      const existingId = await q.findAuthUserIdByEmail(service, parsed.data.email)
      if (existingId) {
        return errorFlatMessage(
          'This email already exists',
          ErrorCodes.DUPLICATE_RESOURCE.status,
          request,
        )
      }

      const { data: created, error: createError } =
        await service.auth.admin.createUser({
          email: parsed.data.email,
          password: randomBytes(32).toString('hex'),
          email_confirm: false,
          user_metadata: {
            user_type: 'staff',
          },
        })

      if (createError || !created.user?.id) {
        const msg = createError?.message ?? 'Failed to create user'
        if (/already|registered|exists/i.test(msg)) {
          return errorFlatMessage(
            'This email already exists',
            ErrorCodes.DUPLICATE_RESOURCE.status,
            request,
          )
        }
        return error(ErrorCodes.INTERNAL_ERROR, request, { message: msg })
      }

      newUserId = created.user.id

      const inviteToken = randomBytes(32).toString('hex')
      const tokenHash = hashStaffInviteToken(inviteToken)
      const expiresAt = new Date(
        Date.now() + STAFF_INVITE_TOKEN_EXPIRY_DAYS * 24 * 60 * 60 * 1000,
      ).toISOString()
      const appMetadata = created.user.app_metadata ?? {}

      const { error: metaError } = await service.auth.admin.updateUserById(
        newUserId,
        {
          app_metadata: {
            ...appMetadata,
            staff_invite_token_hash: tokenHash,
            staff_invite_expires_at: expiresAt,
            staff_invite_sent_at: new Date().toISOString(),
          },
        },
      )

      if (metaError) {
        console.error('[StaffManagementInviteStaff] Failed to store invite token', {
          message: metaError.message,
        })
        return error(ErrorCodes.INTERNAL_ERROR, request, { message: metaError.message })
      }

      const result = await q.inviteStaff({
        propertyId,
        userId: newUserId,
        role: firstRole,
        roleCategoryIds,
        status: parsed.data.status ?? 'pending',
      })

      if (access.companyId) {
        await recordActivityLog(service, {
          companyId: access.companyId,
          propertyId,
          action: 'create',
          resource: 'staff',
          userId: user.id,
          details: `Invited staff ${parsed.data.email} with role ${firstRole}.`,
        })
      }

      const baseUrl = getInviteBaseUrl()
      const inviteUrl = `${baseUrl}/staff-invite?token=${encodeURIComponent(inviteToken)}&uid=${encodeURIComponent(newUserId)}`
      const html = await buildStaffInviteLinkEmailHtml(
        inviteUrl,
        undefined,
        `${STAFF_INVITE_TOKEN_EXPIRY_DAYS} days`,
      )
      const emailResult = await sendEmail({
        to: parsed.data.email,
        subject: "You're invited to CampOS — complete your registration",
        html,
        text: `You've been invited to join a property on CampOS. Create your password here (link expires in ${STAFF_INVITE_TOKEN_EXPIRY_DAYS} days):\n${inviteUrl}\n`,
      })

      if (!emailResult.success) {
        console.error('[StaffManagementInviteStaff] Invite email failed', {
          error: emailResult.error,
        })
        return error(ErrorCodes.INTERNAL_ERROR, request, {
          message: emailResult.error,
        })
      }

      if (access.companyId) {
        await recordActivityLog(service, {
          companyId: access.companyId,
          propertyId,
          action: 'create',
          resource: 'staff_invite_email',
          userId: null,
          details: `System sent staff invite email to ${parsed.data.email}.`,
        })
      }

      return success({ ...result, emailSent: true }, request)
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : 'Unknown error'
      return error(ErrorCodes.INTERNAL_ERROR, request, { message })
    }
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unknown error'
    console.error('[StaffManagementInviteStaff] Invite failed', { message, err })
    return error(ErrorCodes.INTERNAL_ERROR, request, { message })
  }
}

import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'
import { createServiceRoleClient } from '@/lib/supabase/service-role'
import { StaffManagementQueries } from '@/lib/dashboard/staff-management-queries'
import { createHash } from 'crypto'

const EXPIRY_BUFFER_MS = 60 * 1000

function hashToken(token: string): string {
  return createHash('sha256').update(token).digest('hex')
}

function validateStaffInviteToken(
  appMetadata: Record<string, unknown>,
  token: string,
): { valid: true } | { valid: false; error: 'expired' | 'invalid_link' } {
  const storedHash = appMetadata.staff_invite_token_hash as string | undefined
  const expiresAt = appMetadata.staff_invite_expires_at as string | undefined

  if (!storedHash || !expiresAt) {
    return { valid: false, error: 'invalid_link' }
  }

  const isExpired =
    new Date(expiresAt).getTime() < Date.now() - EXPIRY_BUFFER_MS
  if (isExpired) {
    return { valid: false, error: 'expired' }
  }

  const inputHash = hashToken(token)
  if (inputHash !== storedHash) {
    return { valid: false, error: 'invalid_link' }
  }

  return { valid: true }
}

export async function GET(request: NextRequest) {
  try {
    const url = new URL(request.url)
    const token = url.searchParams.get('token')
    const uid = url.searchParams.get('uid')

    if (!token || !uid) {
      return NextResponse.json({ valid: false, error: 'invalid_link' }, { status: 400 })
    }

    const serviceClient = createServiceRoleClient()
    const { data: userData, error: userError } =
      await serviceClient.auth.admin.getUserById(uid)

    if (userError || !userData?.user) {
      return NextResponse.json({ valid: false, error: 'invalid_link' }, { status: 400 })
    }

    const authUser = userData.user
    const appMetadata = (authUser.app_metadata ?? {}) as Record<string, unknown>
    const result = validateStaffInviteToken(appMetadata, token)

    if (!result.valid) {
      return NextResponse.json({ valid: false, error: result.error })
    }

    const userMeta = (authUser.user_metadata ?? {}) as Record<string, unknown>
    const firstName =
      typeof userMeta.first_name === 'string' ? userMeta.first_name : ''
    const lastName =
      typeof userMeta.last_name === 'string' ? userMeta.last_name : ''
    const contactPhone =
      typeof userMeta.contact_phone === 'string'
        ? userMeta.contact_phone
        : authUser.phone ?? ''

    const q = new StaffManagementQueries(serviceClient as any)
    const { roleLabel, categoryNames } =
      await q.getStaffInviteStaffContextByUserId(uid)

    return NextResponse.json({
      valid: true,
      email: authUser.email ?? '',
      firstName,
      lastName,
      contactPhone,
      roleLabel,
      categoryNames,
    })
  } catch (error) {
    console.error('[StaffInviteRegister GET] Unexpected error:', error)
    return NextResponse.json(
      { valid: false, error: 'invalid_link' },
      { status: 500 },
    )
  }
}

export async function POST(request: Request) {
  try {
    const body = await request.json().catch(() => ({}))
    const token = typeof body?.token === 'string' ? body.token : null
    const uid = typeof body?.uid === 'string' ? body.uid : null
    const password = typeof body?.password === 'string' ? body.password : null
    const firstName =
      typeof body?.firstName === 'string' ? body.firstName.trim() : ''
    const lastName =
      typeof body?.lastName === 'string' ? body.lastName.trim() : ''
    const contactPhone =
      typeof body?.contactPhone === 'string' ? body.contactPhone.trim() : ''

    if (!token || !uid || !password) {
      return NextResponse.json(
        { error: 'Token, uid, and password are required.' },
        { status: 400 },
      )
    }

    if (!firstName || !lastName) {
      return NextResponse.json(
        { error: 'First name and last name are required.' },
        { status: 400 },
      )
    }

    if (password.length < 8) {
      return NextResponse.json(
        { error: 'Password must be at least 8 characters.' },
        { status: 400 },
      )
    }

    const serviceClient = createServiceRoleClient()
    const { data: userData, error: userError } =
      await serviceClient.auth.admin.getUserById(uid)

    if (userError || !userData?.user) {
      return NextResponse.json(
        { error: 'Invalid or expired link. Ask your property admin to resend the invite.' },
        { status: 400 },
      )
    }

    const user = userData.user
    const appMetadata = user.app_metadata ?? {}
    const userMetadata = (user.user_metadata ?? {}) as Record<string, unknown>
    const result = validateStaffInviteToken(
      appMetadata as Record<string, unknown>,
      token,
    )

    if (!result.valid) {
      return NextResponse.json(
        {
          error:
            result.error === 'expired'
              ? 'This invitation link has expired. Ask your property admin to invite you again.'
              : 'Invalid or expired link. Ask your property admin to resend the invite.',
        },
        { status: 400 },
      )
    }

    const nextUserMetadata = {
      ...userMetadata,
      first_name: firstName,
      last_name: lastName,
      contact_phone: contactPhone,
      user_type: 'staff',
    }

    const { error: updateError } = await serviceClient.auth.admin.updateUserById(
      uid,
      {
        password,
        email_confirm: true,
        user_metadata: nextUserMetadata,
        app_metadata: {
          ...appMetadata,
          staff_invite_token_hash: null,
          staff_invite_expires_at: null,
          staff_invite_sent_at: null,
        },
      },
    )

    if (updateError) {
      console.error('[StaffInviteRegister] Failed to update user:', updateError)
      return NextResponse.json(
        { error: 'Failed to set password. Please try again.' },
        { status: 500 },
      )
    }

    const staffQueries = new StaffManagementQueries(serviceClient as any)
    try {
      await staffQueries.activatePendingStaffForUser(uid)
    } catch (staffErr) {
      console.error('[StaffInviteRegister] property_staff activation failed', staffErr)
      return NextResponse.json(
        {
          error:
            'Your password was set, but we could not activate your staff access. Please contact support.',
        },
        { status: 500 },
      )
    }

    console.log('[StaffInviteRegister] Password set for invited staff user:', uid)
    return NextResponse.json({ success: true })
  } catch (error) {
    console.error('[StaffInviteRegister POST] Unexpected error:', error)
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 },
    )
  }
}

"use client"

import type React from "react"
import { useState, useEffect, Suspense } from "react"
import Link from "next/link"
import { useRouter, useSearchParams } from "next/navigation"
import { MotionDiv } from "@/components/ui/motion-wrapper"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Badge } from "@/components/ui/badge"
import { Icons } from "@/components/icons"
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Alert, AlertDescription } from "@/components/ui/alert"
import { Eye, EyeOff } from "lucide-react"

type InviteContext = {
  email: string
  firstName: string
  lastName: string
  contactPhone: string
  roleLabel: string
  categoryNames: string[]
}

function StaffInviteContent() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const token = searchParams.get("token")
  const uid = searchParams.get("uid")
  const linkError = searchParams.get("error")

  const [context, setContext] = useState<InviteContext | null>(null)
  const [firstName, setFirstName] = useState("")
  const [lastName, setLastName] = useState("")
  const [contactPhone, setContactPhone] = useState("")
  const [password, setPassword] = useState("")
  const [confirmPassword, setConfirmPassword] = useState("")
  const [error, setError] = useState<string | null>(null)
  const [loading, setLoading] = useState(false)
  const [validating, setValidating] = useState(true)
  const [linkValid, setLinkValid] = useState<boolean | null>(null)
  const [showPassword, setShowPassword] = useState(false)
  const [showConfirmPassword, setShowConfirmPassword] = useState(false)

  useEffect(() => {
    if (linkError === "expired") {
      setLinkValid(false)
      setValidating(false)
      return
    }
    if (!token || !uid) {
      setLinkValid(false)
      setValidating(false)
      return
    }
    const check = async () => {
      try {
        const res = await fetch(
          `/api/auth/staff-invite-register?token=${encodeURIComponent(token)}&uid=${encodeURIComponent(uid)}`,
        )
        const data = await res.json()
        if (data.valid === true) {
          setLinkValid(true)
          setContext({
            email: typeof data.email === "string" ? data.email : "",
            firstName: typeof data.firstName === "string" ? data.firstName : "",
            lastName: typeof data.lastName === "string" ? data.lastName : "",
            contactPhone:
              typeof data.contactPhone === "string" ? data.contactPhone : "",
            roleLabel: typeof data.roleLabel === "string" ? data.roleLabel : "—",
            categoryNames: Array.isArray(data.categoryNames)
              ? data.categoryNames.filter((x: unknown) => typeof x === "string")
              : [],
          })
          setFirstName(typeof data.firstName === "string" ? data.firstName : "")
          setLastName(typeof data.lastName === "string" ? data.lastName : "")
          setContactPhone(
            typeof data.contactPhone === "string" ? data.contactPhone : "",
          )
        } else {
          setLinkValid(false)
        }
      } catch {
        setLinkValid(false)
      } finally {
        setValidating(false)
      }
    }
    void check()
  }, [token, uid, linkError])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError(null)
    if (!firstName.trim() || !lastName.trim()) {
      setError("First name and last name are required")
      return
    }
    if (password !== confirmPassword) {
      setError("Passwords do not match")
      return
    }
    if (password.length < 8) {
      setError("Password must be at least 8 characters")
      return
    }
    if (!token || !uid) return
    setLoading(true)
    try {
      const res = await fetch("/api/auth/staff-invite-register", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          token,
          uid,
          password,
          firstName: firstName.trim(),
          lastName: lastName.trim(),
          contactPhone: contactPhone.trim(),
        }),
      })
      const data = await res.json()
      if (!res.ok) {
        setError(data.error || "Failed to complete registration. Please try again.")
        setLoading(false)
        return
      }
      router.push("/login?staff_invite=success")
    } catch {
      setError("Something went wrong. Please try again.")
    } finally {
      setLoading(false)
    }
  }

  if (validating) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-background via-background to-muted/20 px-4">
        <div className="flex flex-col items-center gap-4">
          <Icons.spinner className="h-8 w-8 animate-spin text-muted-foreground" />
          <p className="text-sm text-muted-foreground">Checking invitation…</p>
        </div>
      </div>
    )
  }

  if (linkValid === false) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-background via-background to-muted/20 px-4">
        <MotionDiv
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
          className="w-full max-w-md"
        >
          <div className="text-center mb-8">
            <Link href="/" className="inline-flex items-center space-x-2 mb-6">
              <Icons.logo className="h-8 w-8" />
              <span className="font-heading text-2xl">CampOS</span>
            </Link>
          </div>
          <Card className="glassmorphic-card border-border/50 text-center">
            <CardHeader>
              <CardTitle className="text-amber-600 dark:text-amber-500">
                Link invalid or expired
              </CardTitle>
              <CardDescription>
                This staff invitation link is no longer valid. Ask your property
                admin to send a new invite.
              </CardDescription>
            </CardHeader>
            <CardFooter className="flex justify-center">
              <Button asChild className="neumorphic-button-primary">
                <Link href="/login">Go to Login</Link>
              </Button>
            </CardFooter>
          </Card>
        </MotionDiv>
      </div>
    )
  }

  const roleLabel = context?.roleLabel ?? "—"
  const categoryNames = context?.categoryNames ?? []
  const emailDisplay = context?.email ?? ""

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-background via-background to-muted/20 px-4 py-10">
      <MotionDiv
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
        className="w-full max-w-xl"
      >
        <div className="text-center mb-8">
          <Link href="/" className="inline-flex items-center space-x-2 mb-6">
            <Icons.logo className="h-8 w-8" />
            <span className="font-heading text-2xl">CampOS</span>
          </Link>
          <h1 className="text-3xl font-heading font-bold text-balance">
            Complete your registration
          </h1>
          <p className="text-muted-foreground mt-2">
            Confirm your details and create a password for your staff account
          </p>
        </div>

        <Card className="glassmorphic-card border-border/50">
          <CardHeader className="pb-1 sm:pb-2">
            <CardTitle>Your profile</CardTitle>
            <CardDescription>
              Role and categories match your invitation and cannot be changed here
            </CardDescription>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSubmit} className="space-y-4">
              {error ? (
                <Alert variant="destructive">
                  <AlertDescription>{error}</AlertDescription>
                </Alert>
              ) : null}

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="firstName">First name</Label>
                  <Input
                    id="firstName"
                    autoComplete="given-name"
                    value={firstName}
                    onChange={(e) => setFirstName(e.target.value)}
                    required
                    disabled={loading}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="lastName">Last name</Label>
                  <Input
                    id="lastName"
                    autoComplete="family-name"
                    value={lastName}
                    onChange={(e) => setLastName(e.target.value)}
                    required
                    disabled={loading}
                  />
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="email">Email</Label>
                <Input
                  id="email"
                  type="email"
                  autoComplete="email"
                  value={emailDisplay}
                  disabled
                  className="bg-muted/50 text-muted-foreground"
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="contactPhone">Contact number</Label>
                <Input
                  id="contactPhone"
                  type="tel"
                  autoComplete="tel"
                  placeholder="e.g. +1 555 123 4567"
                  value={contactPhone}
                  onChange={(e) => setContactPhone(e.target.value)}
                  disabled={loading}
                />
              </div>

              <div className="border-b border-border pb-4 space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="password">Password</Label>
                  <div className="relative">
                    <Input
                      id="password"
                      type={showPassword ? "text" : "password"}
                      placeholder="••••••••"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      required
                      disabled={loading}
                      className="pr-10"
                    />
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon"
                      className="absolute right-0 top-0 h-full px-3 py-2 hover:bg-transparent"
                      onClick={() => setShowPassword((prev) => !prev)}
                      disabled={loading}
                      aria-label={showPassword ? "Hide password" : "Show password"}
                    >
                      {showPassword ? (
                        <EyeOff className="h-4 w-4 text-muted-foreground" />
                      ) : (
                        <Eye className="h-4 w-4 text-muted-foreground" />
                      )}
                    </Button>
                  </div>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="confirmPassword">Confirm password</Label>
